        private string BinaryBitMask;
        private string Numbering;
        private string ReverseBraille;
        private int ReverseUnicodeDec;
        private string ReverseUnicodeHex;
        private byte ReverseUnicode28Position;
        private string ReverseUnicode28PositionBinary;
        private string ReverseBinaryBitMask;
        private string ReverseNumbering;
        private byte BitCount;
        private string BrailleRow;


        private static Dictionary<int, BrailleTable> brailleTableItems =
