        private BrailleTable(
            int id, string braille, int unicodeDec,
            string unicodeHex, byte unicode28Position, string unicode28PositionBinary,
            string binaryBitMask, string numbering, string reverseBraille,
            int reverseUnicodeDec, string reverseUnicodeHex, byte reverseUnicode28Position,
            string reverseUnicode28PositionBinary, string reverseBinaryBitMask, string reverseNumbering,
            byte bitCount, string brailleRow)
        {
            this.ID = id;
            this.Braille = braille;
            this.UnicodeDec = unicodeDec;
            this.UnicodeHex = unicodeHex;
            this.Unicode28Position = unicode28Position;
            this.Unicode28PositionBinary = unicode28PositionBinary;
            this.BinaryBitMask = binaryBitMask;
            this.Numbering = numbering;
            this.ReverseBraille = reverseBraille;
            this.ReverseUnicodeDec = reverseUnicodeDec;
            this.ReverseUnicodeHex = reverseUnicodeHex;
            this.ReverseUnicode28Position = reverseUnicode28Position;
            this.ReverseUnicode28PositionBinary = reverseUnicode28PositionBinary;
            this.ReverseBinaryBitMask = reverseBinaryBitMask;
            this.ReverseNumbering = reverseNumbering;
            this.BitCount = bitCount;
            this.BrailleRow = brailleRow;
        }


        public static T GetByIndex<T>(byte index, byte data)
        {
            object value = data switch
            {
                0 => brailleTableItems[index].ID,
                1 => brailleTableItems[index].Braille,
                2 => brailleTableItems[index].UnicodeDec,
                3 => brailleTableItems[index].UnicodeHex,
                4 => brailleTableItems[index].Unicode28Position,
                5 => brailleTableItems[index].Unicode28PositionBinary,
                6 => brailleTableItems[index].BinaryBitMask,
                7 => brailleTableItems[index].Numbering,
                8 => brailleTableItems[index].ReverseBraille,
                9 => brailleTableItems[index].ReverseUnicodeDec,
                10 => brailleTableItems[index].ReverseUnicodeHex,
                11 => brailleTableItems[index].ReverseUnicode28Position,
                12 => brailleTableItems[index].ReverseUnicode28PositionBinary,
                13 => brailleTableItems[index].ReverseBinaryBitMask,
                14 => brailleTableItems[index].ReverseNumbering,
                15 => brailleTableItems[index].BitCount,
                16 => brailleTableItems[index].BrailleRow,
                _ => throw new ArgumentOutOfRangeException(nameof(data))
            };

            return (T)value;
        }


